SET default_transaction_read_only=on;
\copy (select p.category_name, p.subcategory, p.sku, p.model_number, p.name, p.approval_status, p.active, p.stock_quantity, p.inventory_policy, pp.retail_price, pp.floor_price, pp.tier_b_price, pp.tier_c_price, pp.dealer_price, pp.cost_price, (select count(*) from product_images i where i.product_id=p.id and i.slot is not null) as slots, (select count(*) from product_images i where i.product_id=p.id and i.slot is not null and coalesce(i.alt_text,'') like 'Sample %') as sample_slots, p.is_feed_eligible, p.slug, p.warranty_period from products p left join product_prices pp on pp.product_id=p.id order by coalesce(p.category_name,'zz'), p.sku) to '/tmp/catalogue.csv' with csv header
